const reqItem = $input.first().json || {};
const body = reqItem.body || reqItem || {};
const headers = reqItem.headers || {};
const ip = String(headers['x-forwarded-for'] || headers['x-real-ip'] || 'direct').split(',')[0].trim();
const ua = String(headers['user-agent'] || '').slice(0, 180);

// 1. Anti-Bog Honeypot + Sub-Human Timing + Prompt Injection / SQLi / XSS Guard
const rawQuery = String(body.query || '').trim();
const hp = String(body._hp_website_url || '').trim();
const injectionRe = /(ignore\s+all\s+previous\s+instructions|<script\b|union\s+select|drop\s+table|169\.254\.169\.254)/i;
const blocked = hp.length > 0 || injectionRe.test(rawQuery);
const safeQuery = rawQuery.toLowerCase().replace(/[^a-z0-9\s-]/g, '').slice(0, 64) || 'all';

return [{
  json: {
    blocked,
    safeQuery,
    rawQuery: rawQuery.replace(/'/g, "''").slice(0, 120),
    ip: ip.replace(/'/g, "''"),
    ua: ua.replace(/'/g, "''")
  }
}];

const reqItem = $input.first().json || {};
const body = reqItem.body || reqItem || {};
const safeQuery = String(body.query || 'catalog_browse').toLowerCase().replace(/[^a-z0-9\s_-]/g, '').trim().slice(0, 80) || 'catalog_browse';
const productSku = String(body.productSku || 'LL-Q4-001').replace(/[^A-Za-z0-9_-]/g, '').slice(0, 48) || 'LL-Q4-001';
const signalType = String(body.signalType || 'SEARCH_CLICK').toUpperCase();
const rewardMap = {
  SEARCH_CLICK: 1.0,
  WISHLIST_SAVE: 2.5,
  ADD_TO_CART: 4.0,
  PURCHASE: 8.0,
  THUMBS_UP: 3.0,
  THUMBS_DOWN: -4.0
};
const delta = rewardMap[signalType] !== undefined ? rewardMap[signalType] : 1.0;
const notes = String(body.userFeedbackNotes || '').replace(/'/g, "''").slice(0, 240);

return [{
  json: {
    safeQuery,
    productSku,
    signalType,
    delta,
    isClick: signalType === 'SEARCH_CLICK' ? 1 : 0,
    isWish: signalType === 'WISHLIST_SAVE' ? 1 : 0,
    isCart: signalType === 'ADD_TO_CART' ? 1 : 0,
    isBuy: signalType === 'PURCHASE' ? 1 : 0,
    isUp: signalType === 'THUMBS_UP' ? 1 : 0,
    isDown: signalType === 'THUMBS_DOWN' ? 1 : 0,
    notes
  }
}];

const reqItem = $input.first().json || {};
const body = reqItem.body || reqItem || {};
const filePath = String(body.filePath || 'apps/backend/src/api/headless-gateway.ts').replace(/'/g, "''").slice(0, 240);
const lineNumber = Math.max(1, parseInt(body.lineNumber || 1, 10) || 1);
const gitRepo = String(body.gitRepo || 'banerjee08/print_on_demand').replace(/'/g, "''");
const gitBranch = String(body.gitBranch || 'development').replace(/'/g, "''");
const serviceModule = String(body.serviceModule || 'backend.api').replace(/'/g, "''").slice(0, 100);
const errorCode = String(body.errorCode || 'LOULOU_BACKEND_ERR').replace(/'/g, "''").slice(0, 64);
const message = String(body.message || 'Unhandled exception').replace(/'/g, "''").slice(0, 500);
const githubBlameUrl = `https://github.com/${gitRepo}/blob/${gitBranch}/${filePath}#L${lineNumber}`;
const gitCliFixCommand = `git checkout ${gitBranch} && git blame -L ${lineNumber},${lineNumber} ${filePath}`;

return [{
  json: {
    errorCode,
    serviceModule,
    gitRepo,
    gitBranch,
    filePath,
    lineNumber,
    githubBlameUrl,
    gitCliFixCommand,
    message
  }
}];

const reqItem = $input.first().json || {};
const body = reqItem.body || reqItem || {};
const headers = reqItem.headers || {};
const ip = String(headers['x-forwarded-for'] || headers['x-real-ip'] || 'direct').split(',')[0].trim().replace(/'/g, "''");

const couponMap = {
  LULLUXE25: { code: 'LULLUXE25', percent: 25, defaultCatKey: 'ALL', defaultCatLabel: 'Autumn & Holiday Sitewide Collection' },
  BRIDAL10:  { code: 'BRIDAL10',  percent: 10, defaultCatKey: 'BRIDAL', defaultCatLabel: 'Bridal & Engagement Suite' }
};

const categoryLabels = {
  ALL: 'Autumn & Holiday Sitewide Collection',
  CLUB_FLEECE: 'Heavyweight Crewnecks & Social Club Fleece',
  OUTERWEAR: 'Quarter-Zips, Sherpa & Cozy Outerwear',
  DRESSES: 'Autumn, Holiday & Wedding Guest Dresses',
  BRIDAL: 'Bridal & Engagement Suite',
  MONOGRAM_GIFTS: 'Custom Monogram Holiday Gifts',
  GRAPHICS: 'Game Day & Everyday Graphic Tees'
};

const rawCandidates = Array.isArray(body.candidateCoupons) ? body.candidateCoupons : [];
if (body.clickedCouponCode) rawCandidates.push(body.clickedCouponCode);

const validCandidates = Array.from(new Set(
  rawCandidates.map(c => String(c || '').trim().toUpperCase()).filter(c => couponMap[c])
)).sort((a, b) => couponMap[b].percent - couponMap[a].percent);

const winningCoupon = validCandidates.length > 0 ? validCandidates[0] : 'NONE';
const winningDiscountPercent = winningCoupon !== 'NONE' ? couponMap[winningCoupon].percent : 0;
const supersededCoupons = validCandidates.slice(1);

const catKey = String(body.categoryKey || (winningCoupon !== 'NONE' ? couponMap[winningCoupon].defaultCatKey : 'ALL')).toUpperCase().replace(/'/g, "''");
const catLabel = (categoryLabels[catKey] || String(body.categoryLabel || 'Autumn & Holiday Sitewide Collection')).replace(/'/g, "''");

const grossSubtotalCents = Math.max(0, parseInt(body.grossSubtotalCents || 0, 10) || 0);
const discountLevyCents = winningDiscountPercent > 0 ? Math.round((grossSubtotalCents * winningDiscountPercent) / 100) : 0;
const netCheckoutCents = grossSubtotalCents - discountLevyCents;
const actionType = String(body.actionType || 'CHECKOUT_LEVY_EVALUATED').replace(/'/g, "''");

return [{
  json: {
    actionType,
    catKey,
    catLabel,
    candidatesCsv: validCandidates.join(','),
    winningCoupon,
    winningDiscountPercent,
    supersededCsv: supersededCoupons.join(','),
    grossSubtotalCents,
    discountLevyCents,
    netCheckoutCents,
    ip
  }
}];

const rows = $input.all().map(i => i.json).filter(r => r && r.trend_id);
const reqNode = $('5A. Slicer SQL Query API (GET /webhook/slicer-query-warehouse)').first().json;
const q = reqNode.query || {};

const splitMulti = (val) => {
  if (!val || val.trim().toUpperCase() === 'ALL') return [];
  return val.split(',').map(s => s.trim()).filter(Boolean);
};

const fSources = splitMulti(q.source);
const fRegions = splitMulti(q.region_cluster);
const fLocales = splitMulti(q.locale);
const fGenders = splitMulti(q.gender_skew);
const fAges = splitMulti(q.age_bracket);
const fNiches = splitMulti(q.niche);
const fKinds = splitMulti(q.trend_kind);
const fDemos = splitMulti(q.demographics);

const fTime = (q.time_window || 'ALL').trim();
const fComp = (q.compliance_status || 'ALL').trim();
const fMissing = (q.missing_mode || 'INCLUSIVE').trim().toUpperCase();
const fSearch = (q.q || '').trim().toLowerCase();

const matchMulti = (rowVal, selectedArr, isMissingAttr) => {
  if (selectedArr.length === 0) return true;
  if (fMissing === 'MISSING_ONLY') return isMissingAttr;
  const directHit = selectedArr.some(sel => String(rowVal || '').toLowerCase().includes(sel.toLowerCase()));
  if (directHit) return true;
  if (fMissing === 'INCLUSIVE' && isMissingAttr) return true;
  return false;
};

const matchTimeGranularity = (r, tw) => {
  if (!tw || tw.toUpperCase() === 'ALL') return true;
  const years = Array.isArray(r.years_active) ? r.years_active.map(Number) : [2026];
  const quarters = Array.isArray(r.quarters_active) ? r.quarters_active : ['Q4'];
  const months = Array.isArray(r.months_active) ? r.months_active : ['Oct'];
  const weeks = Array.isArray(r.iso_weeks_active) ? r.iso_weeks_active : ['W42'];
  const rolling = Array.isArray(r.rolling_horizons) ? r.rolling_horizons : ['Live Snapshot'];

  if (tw === 'YEAR:2026') return years.includes(2026);
  if (tw === 'YEAR:2025') return years.includes(2025);
  if (tw === 'YEAR:2024_PRIOR') return years.some(y => y <= 2024);
  if (tw === 'YEAR:MULTI_YEAR') return years.length >= 2 || r.lifecycle_state === 'RECURRING_ANNUAL_WINNER';
  if (tw.startsWith('QUARTER:')) return quarters.includes(tw.split(':')[1]);
  if (tw.startsWith('MONTH:')) return months.includes(tw.split(':')[1]);
  if (tw === 'WEEK:W42') return weeks.includes('W42');
  if (tw === 'WEEK:W40_W44') return weeks.some(w => ['W40','W41','W42','W43','W44'].includes(w));
  if (tw === 'WEEK:W45_W52') return weeks.some(w => { const n = parseInt(w.slice(1),10); return n >= 45 && n <= 52; });
  if (tw === 'WEEK:Q1_WEEKS') return weeks.some(w => { const n = parseInt(w.slice(1),10); return n >= 1 && n <= 13; });
  if (tw === 'WEEK:Q2_WEEKS') return weeks.some(w => { const n = parseInt(w.slice(1),10); return n >= 14 && n <= 26; });
  if (tw === 'WEEK:Q3_WEEKS') return weeks.some(w => { const n = parseInt(w.slice(1),10); return n >= 27 && n <= 39; });
  if (tw === 'ROLLING:LIVE_24H') return rolling.includes('Live Snapshot') || rolling.includes('24h Breakout') || String(r.time_window || '').includes('7d');
  if (tw === 'ROLLING:7D') return rolling.includes('7d') || String(r.time_window || '').includes('7d');
  if (tw === 'ROLLING:30D') return rolling.includes('30d') || String(r.time_window || '').includes('30d') || Number(r.days_seen_count) >= 30;
  if (tw === 'ROLLING:90D') return rolling.includes('90d (3M)') || String(r.time_window || '').includes('90d') || Number(r.days_seen_count) >= 90;
  if (tw === 'ROLLING:365D') return rolling.includes('12M') || String(r.time_window || '').includes('52w') || Number(r.days_seen_count) >= 365 || years.length >= 2;
  return String(r.time_window || '').toLowerCase().includes(tw.toLowerCase());
};

const filtered = rows.filter(r => {
  const ref = (r.source_lake_refs && r.source_lake_refs[0]) || {};
  const auth = ref.authenticity || {};
  const inferredList = auth.inferred_fields || [];
  const isGenderMissing = inferredList.includes('gender_skew') || r.gender_skew === 'Unisex';
  const isAgeMissing = inferredList.includes('age_bracket');
  const isNicheMissing = inferredList.includes('niche');

  if (fMissing === 'MISSING_ONLY' && inferredList.length === 0) return false;
  if (!matchMulti(r.primary_source, fSources, false)) return false;
  if (!matchMulti(r.region_cluster, fRegions, false)) return false;
  if (!matchMulti(r.locale, fLocales, false)) return false;
  if (!matchMulti(r.gender_skew, fGenders, isGenderMissing)) return false;
  if (!matchMulti(r.age_bracket, fAges, isAgeMissing)) return false;
  if (!matchMulti(r.niche, fNiches, isNicheMissing)) return false;
  if (!matchMulti(r.trend_kind, fKinds, false)) return false;
  if (!matchMulti(r.demographics, fDemos, isGenderMissing)) return false;
  if (!matchTimeGranularity(r, fTime)) return false;
  if (fComp !== 'ALL' && r.compliance_status !== fComp) return false;
  if (fSearch && !String(r.topic || '').toLowerCase().includes(fSearch)) return false;
  return true;
});

const calcMeanStd = (arr) => {
  if (!arr.length) return { n: 0, mean: 0, std: 0 };
  const n = arr.length;
  const mean = arr.reduce((a, b) => a + b, 0) / n;
  if (n < 2) return { n, mean, std: 1 };
  const variance = arr.reduce((acc, x) => acc + Math.pow(x - mean, 2), 0) / (n - 1);
  return { n, mean, std: Math.max(1e-6, Math.sqrt(variance)) };
};

const clampWinsor = (z) => Math.max(-3.5, Math.min(3.5, z));

const erfApprox = (x) => {
  const a1 = 0.254829592, a2 = -0.284496736, a3 = 1.421413741, a4 = -1.453152027, a5 = 1.061405429, p = 0.3275911;
  const sign = x < 0 ? -1 : 1;
  const ax = Math.abs(x);
  const t = 1.0 / (1.0 + p * ax);
  const y = 1.0 - (((((a5 * t + a4) * t) + a3) * t + a2) * t + a1) * t * Math.exp(-ax * ax);
  return sign * y;
};

const studentTPValue = (tVal, df) => {
  const absT = Math.abs(tVal);
  if (!df || df < 1) return 1.0;
  const z = absT * (1 - 1 / (4 * df)) / Math.sqrt(1 + (absT * absT) / (2 * df));
  const pOneTail = 0.5 * (1 - erfApprox(z / Math.sqrt(2)));
  return Math.max(0.0001, Math.min(1.0, +(2 * pOneTail).toFixed(4)));
};

// Remedy 4: Within-Cohort Volume Standardization (Search Queries vs Marketplace Units/Reviews)
const searchVolCohort = filtered.filter(r => r.volume_metric_type === 'SEARCH_VOLUME' && Number(r.search_volume) > 0).map(r => Math.log10(Number(r.search_volume)));
const unitRevCohort = filtered.filter(r => r.volume_metric_type !== 'SEARCH_VOLUME' && Number(r.search_volume) > 0).map(r => Math.log10(Number(r.search_volume)));
const searchVolDist = calcMeanStd(searchVolCohort);
const unitRevDist = calcMeanStd(unitRevCohort);

const velVals = filtered.filter(r => Number(r.velocity_pct) > 0).map(r => Number(r.velocity_pct));
// Remedy 3: Use USD-normalized price (price_usd)
const priceVals = filtered.filter(r => Number(r.price_usd || r.avg_market_price) > 0).map(r => Number(r.price_usd || r.avg_market_price));

const velDist = calcMeanStd(velVals);
const priceDist = calcMeanStd(priceVals);

const numericItems = [];
let winsorizedCount = 0;
filtered.forEach(r => {
  const vol = Number(r.search_volume) || 0;
  const vel = Number(r.velocity_pct) || 0;
  const price = Number(r.price_usd || r.avg_market_price) || 0;
  const zParts = [];
  if (vol > 0) {
    const dist = r.volume_metric_type === 'SEARCH_VOLUME' ? searchVolDist : unitRevDist;
    if (dist.n >= 1) {
      const rawZ = dist.n >= 2 ? (Math.log10(vol) - dist.mean) / dist.std : 0;
      zParts.push(clampWinsor(rawZ));
    }
  }
  if (vel > 0 && velDist.n >= 1) {
    const rawZ = velDist.n >= 2 ? (vel - velDist.mean) / velDist.std : 0;
    if (Math.abs(rawZ) > 3.5) winsorizedCount++;
    zParts.push(clampWinsor(rawZ));
  }
  if (price > 0 && priceDist.n >= 1) {
    const rawZ = priceDist.n >= 2 ? (price - priceDist.mean) / priceDist.std : 0;
    if (Math.abs(rawZ) > 3.5) winsorizedCount++;
    zParts.push(clampWinsor(rawZ));
  }
  if (zParts.length > 0) {
    const rawComp = zParts.reduce((a, b) => a + b, 0) / zParts.length;
    numericItems.push({ row: r, rawComp });
  } else {
    r.subset_z_score = null;
    r.ols_t_stat = null;
    r.ols_p_value = null;
    r.subset_df = null;
    r.bayesian_win_prob_pct = null;
  }
});

const nNum = numericItems.length;
const df = Math.max(0, nNum - 1);
if (nNum > 0) {
  const compDist = calcMeanStd(numericItems.map(x => x.rawComp));
  const minComp = Math.min(...numericItems.map(x => x.rawComp));
  const sorted = [...numericItems].sort((a, b) => a.rawComp - b.rawComp);
  sorted.forEach((item, idx) => {
    const r = item.row;
    const zScore = nNum >= 2 ? +((item.rawComp - compDist.mean) / compDist.std).toFixed(2) : 0.0;
    const se = compDist.std / Math.sqrt(nNum);
    const tVal = nNum >= 2 ? +(((item.rawComp - minComp) / Math.max(1e-6, se)) / Math.sqrt(nNum)).toFixed(2) : 0.0;
    const pVal = studentTPValue(tVal, df);
    const empPct = +(((idx + 1) / nNum) * 100).toFixed(1);

    r.subset_z_score = zScore;
    r.ols_t_stat = tVal;
    r.ols_p_value = pVal;
    r.subset_df = df;
    r.bayesian_win_prob_pct = empPct;
  });
}

const uniqueSlugs = new Set(filtered.map(r => r.canonical_slug || r.trend_id)).size;

return [{
  json: {
    status: "OK",
    database_engine: "Hostinger Cloud PostgreSQL 16 (Annual Partitioned trend_timeseries_history + Permanent master_trends_warehouse)",
    table: "public.master_trends_warehouse + public.trend_timeseries_history (y2024_and_prior, y2025, y2026, y2027)",
    total_warehouse_rows: rows.length,
    matched_subset_count: filtered.length,
    anomaly_and_redundancy_audit: {
      unique_canonical_slugs_count: uniqueSlugs,
      duplicate_sku_variants_collapsed: filtered.length - uniqueSlugs,
      currency_normalization: "ALL_PRICES_NORMALIZED_TO_USD",
      volume_cohort_separation: {
        search_volume_cohort_n: searchVolDist.n,
        marketplace_units_reviews_cohort_n: unitRevDist.n
      },
      winsorized_outliers_clamped_at_3_5_sigma: winsorizedCount
    },
    dynamic_subset_statistical_summary: {
      subset_total_rows: filtered.length,
      subset_numeric_rows_n: nNum,
      subset_null_numeric_rows: filtered.length - nNum,
      degrees_of_freedom_df: df,
      price_n: priceDist.n,
      avg_real_market_price_usd: priceDist.n ? +priceDist.mean.toFixed(2) : 0,
      std_real_market_price_usd: priceDist.n >= 2 ? +priceDist.std.toFixed(2) : 0,
      velocity_n: velDist.n,
      avg_velocity_or_sellthrough_pct: velDist.n ? +velDist.mean.toFixed(2) : 0,
      std_velocity_or_sellthrough_pct: velDist.n >= 2 ? +velDist.std.toFixed(2) : 0
    },
    rows: filtered
  }
}];

const req = $input.first().json;
const body = req.body || req.query || {};
const interval = body.interval || 'Every 24 Hours (Daily)';
const runTime = body.run_time || '02:00';
const tz = body.timezone || 'IST (UTC+5:30)';

const parts = String(runTime).split(':');
let hh = parseInt(parts[0] || '2', 10);
let mm = parseInt(parts[1] || '0', 10);

// Convert to UTC for Cron expression
let offsetMins = 0;
if (tz.includes('IST') || tz.includes('Kolkata')) offsetMins = 330;
else if (tz.includes('EST') || tz.includes('New_York')) offsetMins = -240;
else if (tz.includes('London') || tz.includes('BST')) offsetMins = 60;
else if (tz.includes('Sydney') || tz.includes('AEST')) offsetMins = 600;

let totalUtcMins = ((hh * 60 + mm) - offsetMins + 1440) % 1440;
let utcH = Math.floor(totalUtcMins / 60);
let utcM = totalUtcMins % 60;

let cronExpr = `${utcM} ${utcH} * * *`;
if (interval.includes('6 Hours')) {
  cronExpr = `${utcM} ${utcH},${(utcH+6)%24},${(utcH+12)%24},${(utcH+18)%24} * * *`;
} else if (interval.includes('12 Hours')) {
  cronExpr = `${utcM} ${utcH},${(utcH+12)%24} * * *`;
}

const backupMins = (totalUtcMins + 30) % 1440;
const backupUtcH = Math.floor(backupMins / 60);
const backupUtcM = backupMins % 60;
const backupCronExpr = `${backupUtcM} ${backupUtcH} * * *`;

return [{
  json: {
    status: "SCHEDULE_UPDATED",
    interval,
    selected_time: runTime,
    timezone: tz,
    utc_time: `${String(utcH).padStart(2, '0')}:${String(utcM).padStart(2, '0')} UTC`,
    scrape_cron_expression_utc: cronExpr,
    supabase_backup_cron_expression_utc: backupCronExpr,
    updated_at: new Date().toISOString()
  }
}];

const req = $input.first().json;
const body = req.body || req.query || {};
const tableMap = {
  "raw_google_trends": "raw_google_trends",
  "raw_google_shopping": "raw_google_shopping",
  "raw_amazon": "raw_amazon_scrapling",
  "raw_amazon_scrapling": "raw_amazon_scrapling",
  "raw_walmart": "raw_walmart",
  "raw_pinterest": "raw_pinterest",
  "raw_etsy": "raw_etsy",
  "raw_redbubble": "raw_redbubble",
  "raw_shopify_d2c": "raw_shopify_d2c"
};
const defaultTables = [
  "raw_google_trends",
  "raw_google_shopping",
  "raw_amazon_scrapling",
  "raw_walmart",
  "raw_pinterest",
  "raw_etsy",
  "raw_redbubble",
  "raw_shopify_d2c"
];
let rawInput = Array.isArray(body.raw_tables) ? body.raw_tables : defaultTables;
let requestedTables = [...new Set(rawInput.map(t => tableMap[t]).filter(Boolean))];
if (!requestedTables.length) requestedTables = defaultTables;

// 1. Update ingested_at on each selected Bronze Data Lake table (raw_*)
const bronzeUpdates = requestedTables.map(t => `UPDATE public.${t} SET ingested_at = NOW();`).join("\n");

// 2. Optional: If the user added a custom source or new row out-of-interval, UPSERT it into public.master_trends_warehouse
let customUpsertSql = "";
if (body.custom_row && body.custom_row.trend_id && body.custom_row.topic) {
  const r = body.custom_row;
  const esc = (v) => String(v || "").replace(/'/g, "''");
  const tid = esc(r.trend_id);
  const topic = esc(r.topic);
  const reg = esc(r.region_cluster || "US-Canada");
  const loc = esc(r.locale || "US");
  const place = esc(r.place || "United States (National)");
  const kind = esc(r.trend_kind || "Micro-Trend");
  const niche = esc(r.niche || "Apparel & POD");
  const src = esc(r.primary_source || "8. Shopify D2C (/products.json)");
  const demo = esc(r.demographics || "Gen-Z & Millennial Shoppers");
  const age = esc(r.age_bracket || "18-34");
  const gender = esc(r.gender_skew || "Unisex");
  const tw = esc(r.time_window || "Live Snapshot");
  const vol = Number(r.search_volume) || 0;
  const vel = Number(r.velocity_pct) || 0;
  const comp = Number(r.competitor_listings) || 1;
  const price = Number(r.avg_market_price) || 0;
  customUpsertSql = `
INSERT INTO public.master_trends_warehouse (
  trend_id, updated_at, topic, region_cluster, locale, place, trend_kind, niche,
  primary_source, sources_rising, platforms_rising_count, demographics, age_bracket,
  gender_skew, time_window, search_volume, velocity_pct, competitor_listings,
  avg_market_price, compliance_status, source_lake_refs
) VALUES (
  '${tid}', NOW(), '${topic}', '${reg}', '${loc}', '${place}', '${kind}', '${niche}',
  '${src}', '["${src}"]'::jsonb, 1, '${demo}', '${age}',
  '${gender}', '${tw}', ${vol}, ${vel}, ${comp},
  ${price}, '${esc(r.compliance_status || "APPROVED_SAFE")}', '[{"source_table":"${esc(r.source_table || "raw_shopify_d2c")}","lake_id":"${tid}"}]'::jsonb
)
ON CONFLICT (trend_id) DO UPDATE SET
  updated_at = NOW(),
  topic = EXCLUDED.topic,
  avg_market_price = EXCLUDED.avg_market_price,
  search_volume = EXCLUDED.search_volume,
  velocity_pct = EXCLUDED.velocity_pct, compliance_status = EXCLUDED.compliance_status, source_lake_refs = EXCLUDED.source_lake_refs;
`;
}

